$ErrorActionPreference='Stop';$ScriptDir=Split-Path -Parent $MyInvocation.MyCommand.Path;. (Join-Path (Split-Path -Parent $ScriptDir) 'lib/common.ps1')
if(Test-Command terraform){$v=& terraform version|Select-Object -First 1;if(Test-VersionGE $v '1.7.0'){Write-Ok "Terraform $v ya instalado";exit 0}};if(-not(Test-Command winget)){throw 'winget no disponible'};& winget install --id Hashicorp.Terraform --silent --accept-package-agreements --accept-source-agreements;$machine=[Environment]::GetEnvironmentVariable('PATH','Machine');$user=[Environment]::GetEnvironmentVariable('PATH','User');$env:PATH="$machine;$user";if(-not(Test-Command terraform)){throw 'terraform no disponible tras instalación'};Write-Ok "Terraform $(& terraform version|Select-Object -First 1)"
